/*
 * fox girl: she peeks over a ledge, follows a bee, and ducks away.
 * Adapted from beiwater/fox-girl-loader (MIT), with the author's permission.
 * Every cell is a 2x2 quadrant block with one ink colour; no asset is fetched.
 */
import type { Frame, Meta } from "../types.ts";

export const meta = {
  name: "fox girl",
  category: "scenes",
  note: "a fox girl peeks over a ledge in moving block glyphs",
  cols: 80,
  rows: 60,
  fps: 8,
  loop: 10,
  cell: 1,
  ground: "#ffffff",
  palette: ["#ffffff", "#919191", "#7d7d7d", "#696969", "#535353", "#3d3d3d", "#262626", "#0c0c0c"],
} satisfies Meta;

// Index bits are top-left, top-right, bottom-left, bottom-right.
const QUAD = " ▘▝▀▖▌▞▛▗▚▐▜▄▙▟█";


// Literal runs and backward copies, decoded once per module.
function decode(): Uint8Array {
  const packed = atob(DATA);
  const raw = new Uint8Array(meta.cols * meta.rows * 80);
  let src = 0, dst = 0;
  while (src < packed.length) {
    const tag = packed.charCodeAt(src++);
    if (tag < 128) {
      const count = tag + 1;
      for (let i = 0; i < count; i++) raw[dst++] = packed.charCodeAt(src++);
    } else {
      const count = tag - 128 + 4;
      const distance = packed.charCodeAt(src++) | (packed.charCodeAt(src++) << 8);
      for (let i = 0; i < count; i++) {
        raw[dst] = raw[dst - distance];
        dst++;
      }
    }
  }
  return raw;
}

let cachedFrames: { colors: Uint8Array[]; art: string[] } | undefined;

function frames() {
  if (cachedFrames) return cachedFrames;
  const raw = decode();
  const colors: Uint8Array[] = [];
  const art: string[] = [];
  const cells = meta.cols * meta.rows;
  for (let f = 0; f < 80; f++) {
    const tones = new Uint8Array(cells);
    const lines: string[] = [];
    for (let y = 0; y < meta.rows; y++) {
      let line = "";
      for (let x = 0; x < meta.cols; x++) {
        const i = y * meta.cols + x;
        const cell = raw[f * cells + i];
        tones[i] = cell >> 4;
        line += QUAD[cell & 15];
      }
      lines.push(line);
    }
    colors.push(tones);
    art.push(lines.join("\n"));
  }
  return (cachedFrames = { colors, art });
}

export default function foxGirl(): Frame {
  const { colors, art } = frames();
  return (t, { color } = {}) => {
    const i = ((Math.floor(t * meta.fps) % colors.length) + colors.length) % colors.length;
    if (color) color.set(colors[i]);
    return art[i];
  };
}

